const SYSTEM_CONFIG = {
  appName: "GRW RulesManager-AutoLogger",
  version: "1.0.0",
  timezone: "Asia/Tokyo"
};

/**
 * フォルダ構造を自動アサート（検証）する共通ヘルパー
 * @param {string} folderId 
 * @return {GoogleAppsScript.Drive.Folder}
 */

function assertAndGetFolder_(folderId) {
  try {
    const folder = DriveApp.getFolderById(folderId);
    return folder;
  } catch (e) {
    throw new Error(`指定されたDriveフォルダにアクセスできません（ID確認要）。詳細: ${e.message}`);
  }
}

/**
 * @file 07_TaskManager.gs
 * @description Task 管理および 09_Tasks フォルダの入出力・パース処理モジュール
 */

/**
 * 09_Tasks フォルダ内の全タスクをパースして構造化データを返す
 */
function apiGetTaskList() {
  try {
    const folder = assertAndGetFolder_(DRIVE_STRUCTURE.TASKS);
    const files = folder.getFiles();
    const taskList = [];

    while (files.hasNext()) {
      const file = files.next();
      if (!file.getName().endsWith('.md')) continue;

      const content = file.getBlob().getDataAsString('utf-8');
      const parsed = parseTaskMarkdown_(content, file.getId(), file.getName());
      taskList.push(parsed);
    }

    // 管理番号の降順（新着順）でソート
    return taskList.sort((a, b) => b.seqNumber - a.seqNumber);
  } catch (e) {
    Logger.log('タスク一覧取得エラー: ' + e.message);
    return [];
  }
}

/**
 * 新規タスク作成 API（規約に準拠した命名・メタデータ埋め込み）
 */
function apiCreateTask(data) {
  try {
    const seqNoStr = getNextSequenceNumber(); // 例: "0001"
    const seqNumber = parseInt(seqNoStr, 10);
    const dateStr = Utilities.formatDate(new Date(), SYSTEM_CONFIG.timezone, 'yyyy-MM-dd');

    // 命名規則の適用（半角英数字・指定記号以外はハイフン置換）
    const sanitizedTitle = (data.title || 'General-Task').replace(/[\s ]/g, '-').replace(/[^A-Za-z0-9_\-@!#$()~]/g, '');
    const fileName = 'Task_' + dateStr + '_No.' + seqNoStr + '_' + sanitizedTitle + '.md';
    const overviewFolderUrl = 'https://drive.google.com/drive/folders/' + DRIVE_STRUCTURE.OVERVIEW;

    // テンプレートフォーマットの構築（文字列結合により構文エラーを完全回避）
    const markdownContent = '# [Task-No.' + seqNoStr + '] ' + data.title + '\n\n' +
      '---\n' +
      '- **検出日**: ' + dateStr + '\n' +
      '- **優先度**: ' + (data.priority || 'P2') + '\n' +
      '- **状態**: ' + (data.status || '未対応') + '\n' +
      '- **管理番号**: No.' + seqNoStr + '\n' +
      '- **参照原本パス (Overview)**: ' + overviewFolderUrl + '\n\n' +
      '## 1. 課題・タスク詳細\n' + (data.detail || 'Not specified') + '\n\n' +
      '## 2. 原因・背景\n' + (data.cause || 'Not specified') + '\n\n' +
      '## 3. 対応方針・アクション\n' + ((data.actions && data.actions.length > 0) ? data.actions.map(act => '- [ ] ' + act).join('\n') : '- [ ] 特記事項なし') + '\n\n' +
      '## 4. 申し送り事項・特記事項\n' + (data.notes || 'Not specified') + '\n';

    const folder = assertAndGetFolder_(DRIVE_STRUCTURE.TASKS);
    const file = folder.createFile(fileName, markdownContent, MimeType.PLAIN_TEXT);

    // README ChangeLog（索引）への自動追記連携
    appendChangeLogToReadme(dateStr, 'Task起票: ' + data.title, seqNoStr, '#Task #' + (data.priority || 'P2') + ' #' + (data.status || '未対応'));

    return { success: true, message: 'タスク「' + data.title + ' (No.' + seqNoStr + ')」を作成しました。', fileId: file.getId() };
  } catch (e) {
    return { success: false, message: e.message };
  }
}

/**
 * タスクのステータスおよびチェックリスト状態を更新する API
 */
function apiUpdateTaskStatus(fileId, newStatus) {
  try {
    const file = DriveApp.getFileById(fileId);
    let content = file.getBlob().getDataAsString('utf-8');

    // 状態の書き換え
    content = content.replace(/- \*\*状態\*\*: .*/, '- **状態**: ' + newStatus);

    file.setContent(content);
    return { success: true, message: 'ステータスを「' + newStatus + '」に更新しました。' };
  } catch (e) {
    return { success: false, message: e.message };
  }
}

/**
 * 内部ヘルパー: Markdown からタスク情報を抽出するパーサー
 */
function parseTaskMarkdown_(content, fileId, fileName) {
  const lines = content.split('\n');
  let title = fileName;
  let priority = 'P2';
  let status = '未対応';
  let seqNoStr = '0001';
  let seqNumber = 1;
  let dateStr = '';
  let detail = '';

  lines.forEach(line => {
    if (line.startsWith('# ')) {
      title = line.replace(/#\s*\[.*?\]\s*/, '').trim();
    }
    if (line.includes('**検出日**')) {
      dateStr = line.split(':')[1] ? line.split(':')[1].trim() : '';
    }
    if (line.includes('**優先度**')) {
      priority = line.split(':')[1] ? line.split(':')[1].trim() : 'P2';
    }
    if (line.includes('**状態**')) {
      status = line.split(':')[1] ? line.split(':')[1].trim() : '未対応';
    }
    if (line.includes('**管理番号**')) {
      const match = line.match(/No\.([0-9]+)/);
      if (match) {
        seqNoStr = match[1];
        seqNumber = parseInt(seqNoStr, 10);
      }
    }
  });

  return {
    fileId: fileId,
    fileName: fileName,
    title: title,
    priority: priority,
    status: status,
    seqNoStr: seqNoStr,
    seqNumber: seqNumber,
    dateStr: dateStr,
    url: 'https://drive.google.com/file/d/' + fileId + '/view'
  };
}

/**
 * 定期実行用エントリーポイント（引数なし）
 * 設定したスケジュール（毎日・毎時など）に従って自動で呼び出されます。
 */
function runScheduledTask() {
  try {
    Logger.log('=== 定期実行タスクを開始します ===');

    // 1. 10個の Drive フォルダ構造の自動アサート（整合性チェック）
    Object.keys(DRIVE_STRUCTURE).forEach(key => {
      assertAndGetFolder_(DRIVE_STRUCTURE[key]);
    });
    Logger.log('すべての Drive フォルダ構造（10箇所）の整合性確認（アサート）が完了しました。');

    // 2. 自動巡回タスクの生成（09_Tasks へ保存 ＆ 原本パス埋め込み）
    const today = new Date().toISOString().split('T')[0];
    const taskTitle = `自動定期巡回レポート_${today}`;
    const taskContent = '日次システム巡回および Drive フォルダ構造の整合性自動アサートが正常に完了しました。';

    // 既存のタスク作成関数を呼び出して保存
    const result = createAndSaveTask(taskTitle, taskContent);

    if (result.success) {
      Logger.log('定期タスクの自動保存に成功しました: ' + result.fileUrl);
    } else {
      Logger.log('定期タスクの保存に失敗しました: ' + result.message);
    }

    Logger.log('=== 定期実行タスクが正常に終了しました ===');
  } catch (e) {
    Logger.log('【エラー】定期実行タスクで例外が発生しました: ' + e.message);
    // 必要に応じてエラー時の通知処理などをここに追加できます
  }
}

/**
 * @file 03_NumberingService.gs
 * @description 共通の採番ルール（4桁/8桁ゼロ埋め）を管理するモジュール
 */
function getNextSequenceNumber() {
  const scriptProperties = PropertiesService.getScriptProperties();
  let currentSeq = parseInt(scriptProperties.getProperty('GLOBAL_SEQ_COUNTER') || '0', 10);
  currentSeq += 1;
  scriptProperties.setProperty('GLOBAL_SEQ_COUNTER', currentSeq.toString());

  // 1〜9999は4桁、10000以上は8桁のゼロ埋め
  if (currentSeq <= 9999) {
    return String(currentSeq).padStart(4, '0');
  } else {
    return String(currentSeq).padStart(8, '0');
  }
}

/**
 * @file 05_ReadmeUpdater.gs
 * @description README.md の ChangeLog（索引）へ自動追記するモジュール
 */
function appendChangeLogToReadme(dateStr, title, seqNo, tags) {
  try {
    const readmeFolder = assertAndGetFolder_(DRIVE_STRUCTURE.README);
    const files = readmeFolder.getFilesByName('README.md');

    let readmeFile;
    if (files.hasNext()) {
      readmeFile = files.next();
    } else {
      const initialContent = `# README / ChangeLog - 索引\n\n## ChangeLog - 索引\n\n`;
      readmeFile = readmeFolder.createFile('README.md', initialContent, MimeType.PLAIN_TEXT);
    }

    let content = readmeFile.getBlob().getDataAsString('utf-8');
    const newLogEntry = `##### [${dateStr}] ${title} - No.${seqNo}\ntag: ${tags || '#Project-Milestones'}\n\n`;

    const targetHeader = '## ChangeLog - 索引';
    if (content.includes(targetHeader)) {
      content = content.replace(targetHeader, `${targetHeader}\n\n${newLogEntry}`);
    } else {
      content += `\n${newLogEntry}`;
    }

    readmeFile.setContent(content);
    return true;
  } catch (e) {
    Logger.log(`README 追記エラー: ${e.message}`);
    return false;
  }
}

/**
 * @file 06_GitHubKnowledgeManager.gs
 * @description GitHub リポジトリのナレッジ & Installガイド自動生成モジュール
 */

/**
 * GitHubリポジトリ情報の解析・Markdown自動生成およびフォルダ保存
 */
function apiGenerateGitHubKnowledge(data) {
  try {
    const seqNoStr = getNextSequenceNumber(); // 4桁/8桁ゼロ埋め連番取得
    const dateStr = Utilities.formatDate(new Date(), SYSTEM_CONFIG.timezone, 'yyyy-MM-dd');

    // URLから owner/repository 名を抽出 (例: https://github.com/owner/repo -> owner-repo)
    let repoSlug = 'repository';
    if (data.repoUrl) {
      const match = data.repoUrl.match(/github\.com\/([^\/]+\/[^\/]+)/);
      if (match) {
        repoSlug = match[1].replace('/', '-');
      }
    }

    // 命名規則の適用（半角英数字・指定記号のみ）
    const sanitizedSlug = repoSlug.replace(/[^A-Za-z0-9_\-@!#$()~]/g, '');
    const fileName = 'Repo_' + dateStr + '_No.' + seqNoStr + '_' + sanitizedSlug + '.md';
    const folder = assertAndGetFolder_(DRIVE_STRUCTURE.GITHUB_REPO);
    const folderUrl = 'https://drive.google.com/drive/folders/' + DRIVE_STRUCTURE.GITHUB_REPO;

    // 構造化Markdownの構築
    const markdownContent = '# [Repo-No.' + seqNoStr + '] ' + repoSlug + '\n\n' +
      '---\n' +
      '- **登録日**: ' + dateStr + '\n' +
      '- **管理番号**: No.' + seqNoStr + '\n' +
      '- **リポジトリURL**: ' + (data.repoUrl || 'N/A') + '\n' +
      '- **カテゴリ**: #' + (data.category || 'Tool') + ' #GitHub\n' +
      '- **動作要件**: ' + (data.environment || 'Python / Node.js / Docker') + '\n' +
      '- **参照原本フォルダ**: [github-repository](' + folderUrl + ')\n\n' +
      '---\n\n' +
      '## 1. プロジェクト概要 & 要約\n' +
      '- **目的**: ' + (data.purpose || '本リポジトリが解決する課題やコア機能の解説。') + '\n' +
      '- **主な特徴**:\n' +
      '  - 特徴1: 自動インストール・構成管理のサポート\n' +
      '  - 特徴2: RAG / Local LLM 連携に最適化されたナレッジ構造\n\n' +
      '## 2. 動作要件・前提条件 (Prerequisites)\n' +
      '- 対象環境: ' + (data.environment || '標準ランタイム環境') + '\n' +
      '- 必要な依存関係および API キー設定\n\n' +
      '## 3. Install ガイド & セットアップ手順\n' +
      '```bash\n' +
      '# 1. リポジトリのクローン\n' +
      'git clone ' + (data.repoUrl || '') + '.git\n' +
      'cd ' + repoSlug.split('-').pop() + '\n\n' +
      '# 2. 依存パッケージのインストール・セットアップ\n' +
      '# (環境に応じたセットアップコマンドを実行)\n' +
      '```\n\n' +
      '## 4. 設定ファイル (.env / Config) 仕様\n' +
      '- 必要な環境変数やパラメータ設定の解説。\n\n' +
      '## 5. 実行・使用方法 (Usage)\n' +
      '- 基本実行コマンドおよび主要なオプション引数。\n\n' +
      '## 6. トラブルシューティング & 既知の制約\n' +
      '- よくあるエラーと対処法、依存関係の競合に関する注意点。\n';

    const file = folder.createFile(fileName, markdownContent, MimeType.PLAIN_TEXT);

    // README.md の ChangeLog（索引）へ降順自動追記
    appendChangeLogToReadme(dateStr, 'Repo登録: ' + repoSlug, seqNoStr, '#GitHub #' + (data.category || 'Tool'));

    return {
      success: true,
      message: 'GitHub リポジトリのナレッジドキュメント「' + fileName + '」を自動生成しました。',
      fileId: file.getId(),
      url: 'https://drive.google.com/file/d/' + file.getId() + '/view'
    };
  } catch (e) {
    return { success: false, message: e.message };
  }
}

/**
 * 登録済み GitHub ナレッジの一覧を取得する API
 */
function apiGetGitHubRepoList() {
  try {
    const folder = assertAndGetFolder_(DRIVE_STRUCTURE.GITHUB_REPO);
    const files = folder.getFiles();
    const repoList = [];

    while (files.hasNext()) {
      const file = files.next();
      if (!file.getName().endsWith('.md')) continue;

      repoList.push({
        fileId: file.getId(),
        fileName: file.getName(),
        url: 'https://drive.google.com/file/d/' + file.getId() + '/view'
      });
    }

    return repoList;
  } catch (e) {
    Logger.log('GitHubリポジトリ一覧取得エラー: ' + e.message);
    return [];
  }
}
